from extensions import modules,add
from course import settings,actions,check,p,ul,code,note,step,refs

replay='''import json
from datetime import datetime, timezone
from pathlib import Path
base = Path.home() / "case-m01"
originals = [json.loads(s) for s in (base / "events.ndjson").read_text().splitlines()]
failures = [e for e in originals if e["event"].get("outcome") == "failure" and e["event"]["dataset"] == "linux.auth"]
now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
with (base / "replay.bulk.ndjson").open("w") as out:
    for n in range(10):
        e = json.loads(json.dumps(failures[n % 6]))
        identity = f"REPLAY-M01-{n+1:02}"
        e["event"]["created"] = e["@timestamp"]
        e["@timestamp"] = now
        e["event"]["id"] = identity
        e["labels"]["case_id"] = "M01-REPLAY" if n < 6 else "M01-NEGATIVE"
        e["source"]["ip"] = "10.77.0.12" if n < 6 else "10.77.0.88"
        out.write(json.dumps({"index": {"_id": identity}}) + "\\n")
        out.write(json.dumps(e) + "\\n")
print("Prepared six positive and four negative events at", now)
'''
modules[2]['steps'][5]=step('6. Define and replay a detection honestly',(p('Kibana → Security → Rules/Detection rules → Create new rule → Threshold.') + p('Source index: lab-case-m01. KQL: event.dataset:"linux.auth" and event.outcome:"failure". Group by source.ip and user.name; threshold 5.') + p('Name LAB-M01 repeated failures.') + p('Interval 1 minute; additional look-back 2 minutes.') + actions('Keep external actions off and save enabled.', 'Inspect the execution log for a successful run before generating events.'))+(p('Original evidence is historical.') + p('Save the following script as ~/case-m01/replay.py with nano.') + p('It creates a separate, labeled replay: six current-time failures from .12 and four from .88, preserving the original timestamp in event.created. It never edits the evidence files.'))+code(replay,'ELASTIC01 • Python file ~/case-m01/replay.py')+code('python3 ~/case-m01/replay.py\ncurl --cacert ~/http_ca.crt -u elastic -H "Content-Type: application/x-ndjson" --data-binary @/home/learner/case-m01/replay.bulk.ndjson "https://localhost:9200/lab-case-m01/_bulk?refresh=true" > ~/case-m01/replay-result.json\njq \'{errors,items:(.items|length)}\' ~/case-m01/replay-result.json','ELASTIC01 • Bash')+(check('Require errors:false and ten items.') + p('After at least two successful scheduled executions, open Alerts and filter to this rule and the current time.') + check('Expect a threshold alert for .12/trainee01, and none for .88/trainee01.') + actions('Inspect source events to confirm six versus four; absence of an alert is meaningful only if the rule ran successfully.', 'Capture evidence and disable the rule.', 'If the time window elapsed during troubleshooting, rerun the script and bulk load; stable IDs replace only the ten replay documents.') + p('Scope every original-case query to labels.case_id:"CASE-M01".') + p('Record that this proves scheduled detection of a replay, not live collection or a historical alert.')))

add('ext-04-splunk','E4 · Investigate with Splunk and understand Free limits','E1–E3. Save Elastic evidence before powering ELASTIC01 off.',
'SPLUNK01 only: Ubuntu Server, 6 GB RAM, 2 vCPU, 60 GB disk; review address 10.78.0.41. All other SIEM guests off.',
'Use Splunk Enterprise Search & Reporting to investigate the same 16 records. Splunk is proprietary. Its Free license is a constrained learning option, not a free copy of Splunk Enterprise Security. You will document the license actually installed and avoid claiming unavailable features.',[
step('1. Install the guest and obtain the official package',(p('Create SPLUNK01 using Week 2, allocating the profile above.') + p('Patch Ubuntu on Default Switch and install openssh-server, nano, curl, jq, unzip, and ca-certificates.') + actions('From the official Splunk Enterprise download page choose a supported Linux x86-64 .tgz package; an account and license acceptance may be required.', 'Check the current supported OS matrix before downloading; this course uses Ubuntu 24.04.', 'Record version, filename, download date, and the official checksum.', 'Do not download Enterprise Security, a Universal Forwarder, or a third-party repack.'))+(actions('After patching, move the sole NIC to CyberLab-Review and configure 10.78.0.41/24 without gateway/DNS using E1.', 'Enable ufw with inbound SSH allowed only from 10.78.0.1.', 'Transfer the verified package from the host with scp and name the guest copy ~/splunk.tgz.') + check('Verify its SHA-256 again.') + p('Keep the original versioned filename in your manifest.'))),
step('2. Extract and configure a non-root service account',code('sudo useradd --system --create-home --user-group splunk\nsudo tar -xzf ~/splunk.tgz -C /opt\nsudo chown -R splunk:splunk /opt/splunk\nsudo -u splunk mkdir -p /opt/splunk/etc/system/local\nsudo -u splunk nano /opt/splunk/etc/system/local/web.conf','SPLUNK01 • Bash; fresh installation only')+(actions('Enter the following web.conf.', 'Edit only the local directory, never system/default.') + p('The loopback binding keeps the web interface behind the SSH tunnel even after Free removes authentication.'))+code('[settings]\nhttpport = 8000\nserver.socket_host = 127.0.0.1','SPLUNK01 • web.conf')+(actions('Save and exit.', 'Start as the splunk account, read and accept the license when prompted, and choose a unique administrator credential.', 'Do not put its password on the command line.'))+code('sudo -u splunk /opt/splunk/bin/splunk start\nsudo ss -lntp\nsudo ufw status verbose','SPLUNK01 • Bash')+(check('Require TCP 8000 on 127.0.0.1 only.') + p('The management port 8089 may listen more broadly; guest ufw must block remote access to it.') + p('Do not enable receiving on 9997 or open other guest ports for this file-only lab.'))),
step('3. Connect and identify the license',code('ssh -N -L 8000:127.0.0.1:8000 learner@10.78.0.41','HOST • PowerShell')+(actions('Keep the tunnel open and browse http://localhost:8000.', 'Sign in and choose Search & Reporting.', 'Settings → Licensing: record the license, expiry, and daily allowance.') + p('A new installation normally begins with a 60-day Enterprise trial limited to 500 MB/day. Free also permits 500 MB/day but removes authentication, roles, and alerting. Complete the next searches on either license; the optional trial alert is separate.') + p('Do not enable a paid/cloud trial just to complete this module.'))+code('Test-NetConnection 10.78.0.41 -Port 8000\nTest-NetConnection 10.78.0.41 -Port 8089','HOST • a second PowerShell window')+(check('Both direct tests must fail while the local browser works.') + p('If either succeeds, stop Splunk from the console, correct loopback/firewall settings, then repeat.'))),
step('4. Upload once and validate timestamps',(actions('Settings → Indexes → New Index: name lab_m01, use event data, and save.', 'Settings → Add Data → Upload: choose the host working copy of events.ndjson.') + p('At Set Source Type select the built-in _json type. Preview must show 16 distinct events; expand one to confirm the nested structure.') + p('In timestamp options use the event field @timestamp; where advanced parsing fields are shown use TIME_PREFIX "@timestamp"\\s*:\\s*" and TIME_FORMAT %Y-%m-%dT%H:%M:%SZ with MAX_TIMESTAMP_LOOKAHEAD 20.') + check('Verify the preview resolves to September 1, 2026, 10:00 UTC, not today.') + p('Stop before Submit if preview time or event boundaries are wrong.'))+(p('Input Settings: choose index lab_m01; give the source a recognizable CASE-M01 name and submit once. This upload is one-time indexing, not continuous forwarding.') + p('In Search & Reporting use All time initially; run:'))+code('index=lab_m01\n| spath path=event.id output=case_event_id\n| stats count dc(case_event_id) AS unique_ids min(_time) AS first max(_time) AS last\n| convert ctime(first) ctime(last)','Splunk • SPL')+(check('Require count=16 and unique_ids=16.') + p('Check both boundary times against the fixture answer key, accounting for display timezone.') + p('Duplicate upload is a failed ingestion check: do not use dedup to hide it.') + p('For a mistaken first attempt, create a fresh index lab_m01_retry, repeat once correctly, and substitute that exact index in every query.') + p('Retain the explanation; do not issue broad delete commands.'))),
step('5. Translate the investigation into SPL',code('index=lab_m01\n| spath path=labels.case_id output=case_id\n| spath path=event.dataset output=dataset\n| spath path=event.outcome output=outcome\n| spath path=source.ip output=client\n| spath path=user.name output=username\n| search case_id="CASE-M01" dataset="linux.auth" outcome="failure"\n| stats count BY client username','Splunk • failed-login SPL')+(check('Expect trainee01 at 10.77.0.12 with six failures.') + actions('Use the fixed case time range from E1.', 'Change outcome to success and inspect the two successes; decide whether success alone proves compromise.'))+code('index=lab_m01\n| spath path=event.dataset output=dataset\n| spath path=url.path output=path\n| spath path=http.response.status_code output=status\n| search dataset="web.access"\n| table _time path status\n| sort _time','Splunk • HTTP SPL')+code('index=lab_m01\n| spath path=process.command_line output=command_line\n| search command_line="*CYBERLAB-M01*"\n| table _time command_line','Splunk • process-marker SPL')+(check('Expect four web events (two 404s) and one marker.') + actions('For the negative test use index=lab_m01 | spath path=user.name output=username | search username="nobody-in-this-case" and require zero.', 'Save the three searches as reports where the installed license permits; otherwise export query text and CSV results to your evidence folder.'))),
step('6. Test the license boundary',(p('If using the Enterprise trial, optionally save the failed-login aggregation as an alert that triggers when count ≥ 5, with all external actions off.') + p('Historical data requires an explicit historical search interval or current-time replay; do not claim a scheduled alert was tested by merely saving it. The required Free-path outcome is the saved query/result, not an alert.'))+(actions('After exporting evidence, go to Settings → Licensing → Change license group and select Free license if available, acknowledge the listed losses, and restart when requested.', 'Reopen the SSH tunnel/browser.', 'Record the actual license and confirm that there is no ordinary user-login barrier and alerting is unavailable.', 'If this release/account does not offer Free, stop at the trial and document its expiry; do not fabricate a free entitlement or bypass licensing.') + p('The comparison must then say “trial tested; Free limits documented.”'))),
step('7. Write the operations note and shut down',(actions('Record index size, ingestion allowance used, installed version, time parsing settings, three SPL queries, zero-result check, and the direct-port failures.', 'Explain why a service without authentication cannot be offered as a shared teaching server.', 'Close the tunnel, stop Splunk, and shut down the guest.'))+code('sudo -u splunk /opt/splunk/bin/splunk stop\nsudo poweroff','SPLUNK01 • Bash')+p('On a later session use sudo -u splunk /opt/splunk/bin/splunk start; do not re-extract the installation or re-upload evidence.'))],
['Six failures, four HTTP rows, one marker, and zero non-existent-user matches','16 unique indexed records with original event times','Actual license and verified interface exposure documented'],
['What is lost when the Enterprise trial becomes Free?','Why does querying a file upload not validate endpoint forwarding?'],
'No browser: check service status, loopback listener, SSH tunnel, and port conflicts on the host. No events: begin with All time and the exact index, then inspect timestamp parsing. A blank historical view is not proof that upload failed. Wrong license: use the installed capabilities honestly and record the constraint.',
[('Splunk downloads','https://www.splunk.com/en_us/download/splunk-enterprise.html'),('Linux installation','https://help.splunk.com/en/splunk-enterprise/administer/install-and-upgrade/10.2/install-splunk-enterprise-on-linux-or-macos/install-on-linux'),('Supported platforms','https://help.splunk.com/en/splunk-enterprise/get-started/install-and-upgrade/10.4/plan-your-splunk-enterprise-installation/system-requirements-for-use-of-splunk-enterprise-on-premises'),('Splunk Free limitations','https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.0/configure-splunk-licenses/about-splunk-free'),('Web configuration','https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/web.conf')])

add('ext-05-onion','E5 · Investigate packet evidence in Security Onion','E1, core Week 16, and saved results from E2–E4.',
'SOIMPORT only: 8 GB RAM, 4 vCPU, 200 GB dynamically expanding disk, one management NIC. Other guests off. No live sniffing NIC.',
'Security Onion combines network evidence, detections, and investigation tools. On this laptop you will use IMPORT mode for offline packet evidence. This is not a full live network deployment, and the normalized JSON fixture is not a Windows EVTX file.',[
step('1. Check capacity and get the appliance ISO',(actions('Download the official Security Onion 2.4 ISO from its Download page and compare the published checksum with Get-FileHash on the host.', 'Record the exact release.', 'Use the official ISO, not an Ubuntu network installation.', 'Check host storage in File Explorer → This PC.', 'Keep at least 50 GB free for Windows and growth after the planned lab usage; a dynamically expanding 200 GB disk can still fill the real SSD.') + p('Pause if the combined VM/ISO/checkpoint plan would exceed available storage.'))+p('The hardware page lists a smaller Import disk minimum, while the first-time tutorial specifies 200 GB. This course follows the conservative 200 GB allocation, with 8 GB guest RAM. Evaluation and Standalone are different modes; Standalone’s 24 GB minimum guest RAM does not fit this 16 GB host. A full sensor deployment belongs on a mentor server/cloud environment with separately checked sizing.')),
step('2. Create the VM with one management adapter',(p('In Hyper-V Manager choose <strong>New → Virtual Machine</strong>.') + settings(('Name','SOIMPORT'),('Generation','2'),('Memory','8192 MB, fixed; disable Dynamic Memory.'),('Management adapter','Default Switch'),('Disk','New 200 GB VHDX'),('Installation media','Verified Security Onion ISO')) + actions('Before starting, Settings → Processor → 4 virtual processors, and Security → disable Secure Boot for this guest only if the ISO cannot boot with the selected template.', 'Do not disable host Secure Boot.') + p('This is a Hyper-V adaptation of the vendor ISO workflow, not a claim of a vendor-tested Hyper-V configuration.'))+(p('This guest has a documented management exception: Default Switch provides update/setup connectivity and host browser access. It is not on the isolated live-exercise network.') + actions('Use only the supplied benign packet file, never live attacks or unknown malicious captures.', 'Do not bridge an adapter, forward router ports, or add a sniffing NIC.'))),
step('3. Install the operating system and choose IMPORT',(p('Start the VM and use the ISO’s installation option.') + p('The installer erases the selected virtual disk: verify this is the new SOIMPORT disk.') + p('Set the local account/password when prompted and complete installation.') + p('Eject the ISO when installation finishes and reboot to the installed disk.') + p('Sign in at the VM console; follow the Security Onion Setup prompts.'))+(actions('Select the IMPORT deployment role.', 'Use Standard connectivity for this online setup, hostname soimport, and the single management interface.', 'Select DHCP for the Hyper-V Default Switch; record the assigned IPv4 address, gateway, and DNS.', 'Do not copy an address from the 10.78 review network.', 'Accept a Docker subnet only after verifying it does not overlap the host/VPN networks.', 'Use direct internet access unless your actual connection requires a proxy.'))),
step('4. Create console access and finish setup',(actions('Create the Security Onion Console web account with a unique password (separate from the local operating-system account).', 'For web access choose the management IP when the wizard offers IP versus hostname.', 'Allow analyst access only from the host’s Default Switch IPv4 address: find it in host PowerShell with Get-NetIPAddress -InterfaceAlias "vEthernet (Default Switch)" -AddressFamily IPv4.', 'Do not allow 0.0.0.0/0 or the whole household subnet.', 'Review the setup summary for IMPORT and one management interface before confirming.'))+(actions('Wait for setup completion; first boot can be slow.', 'In the guest use sudo so-status to inspect services.') + p('Browse https:// followed by the recorded guest management IP from the host.') + actions('For the initial self-signed certificate, confirm the address belongs to this guest and record the certificate fingerprint from the browser; do not carry a global certificate-validation bypass into other labs.', 'Sign in and open Grid; wait for the expected Import services to become healthy.') + p('Some screens and labels vary by 2.4 patch; record differences with the mentor.'))),
step('5. Import the PCAP once',(actions('In Grid locate the Import node and its upload/import action.', 'Select the host working copy of web-case.pcap and submit.', 'Wait for processing to finish before searching.') + p('Preserve the original hash and import status. The supported CLI alternative is sudo so-import-pcap /full/path/to/web-case.pcap after an authorized file transfer, but choose one route, not both. Import retains packet timestamps, so “last 15 minutes” will not find this case.'))+(actions('Open Hunt and set the absolute case time range, September 1, 2026, 09:59–10:03 UTC (convert if the UI displays local time).', 'Start with a broad search, expand a record, and use the field action/menu to filter the original client IP 10.77.0.12.', 'Inspect the dataset field and select the Zeek HTTP dataset using the UI filter.') + p('Field names vary with parser versions; copy the resulting query into your notebook rather than assuming the normalized JSON field names were imported.'))),
step('6. Reconstruct four HTTP transactions',(actions('Find the four request paths /, /private.txt, /does-not-exist, and /status.', 'Add time, client/server IP, request URI, and response status to the result columns using the field menu.') + check('Expect four HTTP transactions with statuses 200, 404, 404, 200.') + p('The complete PCAP has 32 packets; packet count is not HTTP transaction count.') + p('Open the related session/PCAP view where available and inspect a request and its empty response.'))+(actions('Use the same query builder to search for /never-requested and require zero HTTP records.', 'Then inspect Alerts for the case interval.') + p('Zero IDS alerts is a valid result for this benign capture; it does not mean ingestion failed.') + actions('Use the HTTP records and import status as ingestion proof.', 'If an informational signature fires, record its rule and explain it without asserting a compromise.') + p('This PCAP contains no SSH or Windows process records, so mark those questions “not observable in this source.”'))),
step('7. Diagnose access and preserve a report',(p('If browser access fails, confirm the guest IP in the console and the current host Default Switch IP; Hyper-V may change this subnet.') + check('Verify so-status before editing firewall rules.') + p('Security Onion manages its firewall; do not make direct iptables changes. To add the actual current host IP, use sudo so-firewall includehost analyst HOST_IP, replacing HOST_IP with the observed address only.') + actions('Remove stale allow entries through Administration → Configuration → firewall host groups after access returns.', 'Never widen to all addresses as a shortcut.'))+(p('Export the query text, four transaction rows, zero-result test, packet/session observation, and alert interpretation.') + p('A repeated identical PCAP may be deduplicated; do not delete backend directories to force another import. Preserve the successful first import and repeat the queries instead.') + p('Sign out and shut down the guest with sudo poweroff.')))],
['IMPORT role, one management interface, restricted host access, and healthy services','Four HTTP transactions and their status codes, with original timestamps','Zero-result test and an explicit account of what the PCAP cannot prove'],
['Why can zero alerts coexist with successful network evidence ingestion?','Why is an IMPORT appliance not a continuous network monitoring deployment?'],
'No results: inspect upload completion, absolute UTC range, and broad records before applying dataset filters. Resource pressure: keep every other VM off and inspect host RAM/storage; extend the exercise on mentor hardware rather than allocating more RAM than the laptop owns. Unsupported ISO/Hyper-V issue: stop and record the boot error for mentor review.',
[('Official download','https://docs.securityonion.net/en/2.4/download.html'),('First-time installation tutorial','https://docs.securityonion.net/en/2.4/first-time-users.html'),('Hardware requirements','https://docs.securityonion.net/en/2.4/hardware.html'),('Deployment modes','https://docs.securityonion.net/en/2.4/architecture.html'),('PCAP import','https://docs.securityonion.net/en/2.4/so-import-pcap.html'),('Managed firewall','https://docs.securityonion.net/en/2.4/firewall.html')])

add('ext-06-compare','E6 · Defend an engineering decision across platforms','Core Weeks 14–16 and E1–E5. Use saved evidence; resume only one appliance at a time.',
'Host for the report; ELASTIC01 alone for the access-control test. No simultaneous SIEM stack.',
'A security professional explains coverage, blind spots, cost, failure modes, and operational ownership. Your final deliverable is a defensible decision for a small organization, supported by experiments rather than product preference.',[
step('1. Build the evidence comparison',(p('Create a table with one column each for Wazuh core labs, Elastic CASE-M01, Splunk CASE-M01, and Security Onion PCAP.') + p('Rows: source/format; live versus file ingestion; timestamps; event count; failed logins; HTTP outcomes; process evidence; positive detection; negative test; role control; retention; backup; resource use; license and expiry.') + p('Use “not tested” or “not observable” where appropriate.') + p('Wazuh used separate live/replayed core exercises; do not claim it ingested the shared 16-event case.'))+p('Reconcile Elastic and Splunk: 16 canonical events, six failures, two successes, four HTTP events with two 404s, and one command marker. Security Onion supports only the four HTTP transactions. Differences caused by replay indexes, duplicates, time zones, or filters must be explained before comparing products.')),
step('2. Demonstrate least privilege in Elastic',(p('Resume ELASTIC01, start es01/kib01, and open the E2 tunnel.') + actions('As the administrator, Kibana → Stack Management → Security → Roles → Create role: lab_case_reader.', 'Leave cluster privileges empty.', 'Add index lab-case-m01 with read and view_index_metadata only.', 'In Kibana privileges grant the current space Discover: Read (and Dashboard: Read only if needed); do not grant All.', 'Save.', 'Create a new local user case_reader with only this role and a unique password through Users.', 'Sign out and test in a separate browser session.'))+(p('The reader should view the saved CASE-M01 data view and read case records.') + actions('If the data view is missing, create it as the administrator in that same space; do not grant management access to fix a saved-object visibility issue.', 'Run these REST checks in the guest using the password prompt:'))+code('curl --cacert ~/http_ca.crt -u case_reader https://localhost:9200/lab-case-m01/_count\ncurl --cacert ~/http_ca.crt -u case_reader -H "Content-Type: application/json" -X PUT https://localhost:9200/lab-case-m01/_doc/reader-must-not-write -d \'{"message":"permission test"}\'','ELASTIC01 • Bash')+(check('Expect count success and HTTP 403 on the write.') + actions('If the write succeeds, the role is too broad: stop, inspect all assigned roles, fix them, remove only that exact test document as administrator, and repeat.', 'Save evidence.') + p('This checks index write denial; it is not a complete authorization audit. Splunk Free cannot provide this equivalent multi-user control.'))),
step('3. Run a controlled fault review',(p('Mentor selects one: hide events with the wrong time window; choose a wrong index/data view; add the bad-date fixture to the transformation input; or stop Kibana while leaving Elasticsearch running. Learner must state a hypothesis, inspect the relevant layer, restore the known configuration, and repeat a positive and negative test.') + p('Do not delete volumes, corrupt evidence, or modify the host firewall for this assessment.') + p('Timebox diagnosis to 30 minutes, then explain the remaining uncertainty.'))),
step('4. Separate lab sizing from operational sizing',(p('Record observed guest RAM, disk growth, startup time, and indexed bytes for each appliance.') + p('These tiny samples cannot establish events-per-second capacity.') + actions('Write a capacity plan identifying the measurements a real deployment needs: daily ingestion, bursts, retention, searchable versus archived storage, replicas, recovery objectives, and simultaneous analysts.', 'Explain why running three different SIEMs would multiply maintenance and parsing work.'))+(p('Record product edition, version, license limits, and source URL with date.') + p('Wazuh is the core security stack; Elastic teaches indexing/pipeline/detection engineering; Splunk teaches SPL and commercial-product limits; Security Onion teaches network evidence.') + p('Do not label every component open source or assume free tiers include premium SIEM functions.'))),
step('5. Present a decision and a 30-day handover',(p('Write a two-page recommendation for a fictional 20-person company: its assets and likely threats; selected primary stack; evidence sources; three testable detections; access roles; retention and recovery; update owner; resource budget; and gaps.') + p('Include a one-page appendix with the comparison table and exact query/configuration filenames. Defend why you would select one primary platform, and when a network tool would complement it.'))+p('Mentor asks: What evidence would change your conclusion? How would you know the collector stopped? What fails during disk exhaustion? Who can read sensitive logs? How would you restore after a failed upgrade? Score explanations and verified evidence, not screenshots alone.')),
step('6. Close the track and rejoin the cloud path',(actions('Disable the replay rule, close tunnels, stop containers, and power off the appliance.', 'Keep original fixtures, configuration exports, query text, hashes, and sanitized reports.', 'Do not put passwords, tokens, or private data in a portfolio.', 'Before deleting any VM, verify an exported report and a documented rebuild path with the mentor; checkpoints are not independent backups.') + p('Continue the core cloud sequence in Weeks 23–25 and attach this comparison to the Week 26 final presentation.')))],
['Reconciled coverage/limitations matrix with actual license and resource observations','Reader query succeeds and unauthorized write returns 403','Mentor-reviewed recommendation, fault diagnosis, and handover plan'],
['Which findings are supported across sources, and which remain unknown?','What evidence would make you change your preferred platform?'],
'Counts differ: return to canonical case label and original index, check duplicates and time range, and separate replay documents. Missing feature: distinguish license limitation from setup failure. A documented limitation is a useful engineering result; an untested claim is not.',
[('Elastic role management','https://www.elastic.co/docs/deploy-manage/users-roles/cluster-or-deployment-auth/kibana-role-management'),('Splunk Free limitations','https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.0/configure-splunk-licenses/about-splunk-free'),('Security Onion architecture','https://docs.securityonion.net/en/2.4/architecture.html')])

def hub():
    body='<div class="eyebrow">Advanced practice / six guided modules</div><h1>Follow the evidence across security platforms.</h1>'
    body+=(p('Add 36 planned hours to the 156-hour core.') + p('Wazuh remains the core stack. These extensions teach Elastic/ELK, Splunk, and Security Onion without requiring all of them to run together. Each module has three two-hour sessions: prepare/build, investigate/test, then troubleshoot/document/review.') + p('Installation delays may require additional practice time.'))
    body+=note('<strong>16 GB laptop rule:</strong> One security appliance at a time. Elastic: 8 GB; Splunk: 6 GB; Security Onion Import: 8 GB. Shut down all other guests. Keep 50 GB of host disk headroom and account for dynamic disks, ISOs, and checkpoint growth. Full Security Onion Standalone is a later mentor-hardware exercise.')
    body+='<h2>Choose a schedule</h2><table><tr><th>Weekly commitment</th><th>How to fit the added labs</th></tr><tr><td>6 hours</td><td>Complete core Weeks 1–22, then E1–E6 over six extra weeks, then core Weeks 23–26. Total: 32 calendar weeks.</td></tr><tr><td>9 hours · recommended</td><td>Keep six hours for core. Use three hours/week for E1 in Weeks 15–16, E2 in 17–18, E3 in 19–20, E4 in 21–22, E5 in 23–24, E6 in 25–26.</td></tr><tr><td>12 hours</td><td>Keep core sequence. Add one six-hour extension per week in Weeks 17–22, leaving cloud Weeks 23–25 and final Week 26.</td></tr></table>'
    body+=(actions('Use failed gates to adjust the calendar; do not rush the operating-system and network foundations.', 'If six months is a firm deadline at six hours/week, retain the original core and defer these extensions.') + p('A mentor can help with ISO downloads and first startup, but the learner should perform and explain the configuration.'))
    body+='<h2>Six modules</h2><div class="cards">'
    for m in modules:body+='<a class="card" href="'+m['slug']+'.html"><span>6 PLANNED HOURS</span><strong>'+m['title']+'</strong><span>'+m['proof'][0]+'</span></a>'
    body+='</div><h2>Shared case and source boundaries</h2>'+p('<a href="case-m01.zip">Download CASE-M01</a>: 16 synthetic normalized events plus a 32-packet HTTP capture. Elastic and Splunk receive the same event file; Security Onion receives only the four HTTP transactions in the PCAP. Wazuh results come from the existing core labs. The answer key is included for mentor review. This case validates file parsing and investigation; the core labs provide live collection experience.')
    body+='<h2>Mentor assessment</h2>'+(p('Score each module out of 10: safe/correct setup (2), reproducible positive and negative tests (3), explanation of evidence and blind spots (3), and clean handover (2). Advance at 8/10 with no unresolved unsafe exposure or false claim of evidence.') + p('Keep configuration, queries, version/license notes, results, troubleshooting notes, and cleanup proof.') + p('E6 is the extension capstone.'))
    body+=(p('Baseline answer key: six failed logins for trainee01, two successful logins total, four HTTP requests with two 404s, one harmless command marker.') + p('Repeated failures followed by a success merit review but do not establish unauthorized access.') + p('No malware or exfiltration is demonstrated.') + p('In E3, the separate replay adds ten current-time documents and must be excluded from original-case counts.'))
    body+='<h2>Comparison report template</h2>'+code('Platform / version / edition / license expiry:\nSource file or live collector and SHA-256:\nOriginal event time / ingest time / displayed timezone:\nExpected count / observed count / differences:\nQuery and positive result:\nNegative query and result:\nDetection test and execution status:\nCoverage and evidence that is unavailable:\nAccess-control test / exposure check:\nRetention / restore plan / observed resource use:\nFault hypothesis / evidence / fix / retest:\nRecommendation / owner / remaining risks:','Copy into your evidence report')
    return body
